using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using LighFight.Runtime;
// Generates a separate review option. Never overwrites the normal Master candidate.
public static class OriginalDenseMasterReviewBuilder {
 const string Source="Assets/LighFight/Art/Drafts/TripoMasterPlayable/MasterHumanoidCandidate.prefab",Dir="Assets/NativeDense/Master";
 static string N(string s)=>s.Substring(s.LastIndexOf(':')+1);
 public static void EnrichNativeBody(){var actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/MasterOriginalDensityReview.prefab"));try{if(PrefabUtility.IsPartOfPrefabInstance(actor))PrefabUtility.UnpackPrefabInstance(actor,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var overlay=actor.GetComponent<NativeSupportOverlay>();var ground=actor.GetComponent<CandidateFootGrounding>();var a=overlay.animator;var data=DensePoseData.Read(AssetDatabase.LoadAssetAtPath<TextAsset>(Dir+"/pose-proof.bytes").bytes);var entry=overlay.entries.Single(e=>e.state=="Defeat");var chosen=new HashSet<int>();var rows=new List<string>{"seconds,phase,fullBodyMinimum,index"};var bones=a.GetComponentsInChildren<Transform>();var pos=bones.Select(t=>t.localPosition).ToArray();var rot=bones.Select(t=>t.localRotation).ToArray();var scale=bones.Select(t=>t.localScale).ToArray();int steps=Mathf.CeilToInt(entry.pose.duration*120);for(int f=0;f<=steps;f++){float phase=Mathf.Min(f/120f/entry.pose.duration,.999999f);ground.ResetForSample();a.Play("Base Layer.Defeat",0,phase);a.Update(0);actor.GetComponent<NativeFingerPoseDriver>().ApplyForReview(false,1);overlay.EvaluateForReview("Defeat",phase,1,false);var matrices=data.Matrices(skin.bones);float min=float.PositiveInfinity;int at=-1;for(int v=0;v<data.vertices.Length;v++){float y=data.Point(v,matrices).y;if(y<min){min=y;at=v;}}chosen.Add(at);rows.Add(f/120f+","+phase+","+min+","+at);if(f%60==0)Debug.Log("Dense full-body original extrema training "+f+"/"+steps);}overlay.defeatBodyPoints=chosen.Select(data.Support).ToArray();for(int i=0;i<bones.Length;i++){bones[i].localPosition=pos[i];bones[i].localRotation=rot[i];bones[i].localScale=scale[i];}ground.shoePoints=overlay.supportPoints;ground.maxCorrection=overlay.baseMaxCorrection;ground.ResetForSample();PrefabUtility.SaveAsPrefabAsset(actor,Dir+"/MasterOriginalDensityReview.prefab");AssetDatabase.SaveAssets();File.WriteAllLines("NativeDenseEvidence/Fighter/body-training-120hz.csv",rows);File.WriteAllLines("NativeDenseEvidence/Fighter/dense-body-indices.txt",chosen.Select(i=>i.ToString()));Debug.Log("AGENT_RESULT native full-body support enriched120Hz points="+chosen.Count);}finally{UnityEngine.Object.DestroyImmediate(actor);}}
 public static void AuditFinalData(){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/MasterOriginalDensityReview.prefab");var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=skin.sharedMesh;var d=DensePoseData.Read(AssetDatabase.LoadAssetAtPath<TextAsset>(Dir+"/pose-proof.bytes").bytes);var vertices=mesh.vertices;var binds=mesh.bindposes;float vertexError=0,bindError=0,weightError=0,sumError=0;for(int k=0;k<vertices.Length;k++)vertexError=Mathf.Max(vertexError,(vertices[k]-d.vertices[k]).magnitude);for(int b=0;b<binds.Length;b++)for(int k=0;k<16;k++)bindError=Mathf.Max(bindError,Mathf.Abs(binds[b][k]-d.binds[b][k]));using(var c=mesh.GetBonesPerVertex())using(var w=mesh.GetAllBoneWeights()){if(c.Length!=d.counts.Length||w.Length!=d.weights.Length)throw new Exception("Final sparse data length mismatch");int offset=0;for(int v=0;v<c.Length;v++){if(c[v]!=d.counts[v])throw new Exception("Final per-vertex influence count mismatch");float sum=0;for(int k=0;k<c[v];k++){if(w[offset].boneIndex!=d.bones[offset])throw new Exception("Final bone influence index mismatch");weightError=Mathf.Max(weightError,Mathf.Abs(w[offset].weight-d.weights[offset]));sum+=w[offset++].weight;}sumError=Mathf.Max(sumError,Mathf.Abs(sum-1));}}
 var native=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/dense-native.prefab").GetComponentInChildren<SkinnedMeshRenderer>();if(!skin.bones.Select(t=>N(t.name)).SequenceEqual(native.bones.Select(t=>N(t.name))))throw new Exception("Serialized final renderer bone order differs from authoritative native order");if(vertexError!=0||bindError!=0||weightError!=0)throw new Exception("Final mesh/proof buffer divergence");File.WriteAllText("NativeDenseEvidence/Fighter/final-data-audit.json","{\"vertexError\":"+vertexError+",\"bindError\":"+bindError+",\"weightError\":"+weightError+",\"weightSumMaximumError\":"+sumError+",\"rendererBoneOrderExact\":true,\"vertices\":"+vertices.Length+"}");Debug.Log("AGENT_RESULT final mesh/proof vertices binds weights names exact; sum error="+sumError);}
 public static void Build(){QualitySettings.skinWeights=SkinWeights.Unlimited;var actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Source));actor.name="Master Original Density Review";try{
 if(PrefabUtility.IsPartOfPrefabInstance(actor))PrefabUtility.UnpackPrefabInstance(actor,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
 var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var a=actor.GetComponentInChildren<Animator>();var ground=actor.GetComponent<CandidateFootGrounding>();var overlay=actor.GetComponent<NativeSupportOverlay>();var view=actor.GetComponent<FighterView>();if(!a.avatar.isHuman||!a.avatar.isValid||!overlay||!view)throw new Exception("Current playable Human/native support candidate required");
 var dense=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/dense-native.prefab").GetComponentInChildren<SkinnedMeshRenderer>();var mesh=dense.sharedMesh;if(mesh.vertexCount!=1031866||mesh.triangles.Length/3!=1992276||dense.bones.Length!=67)throw new Exception("Full original geometry/count gate");
 var names=skin.bones.ToDictionary(t=>N(t.name));var mapped=dense.bones.Select(t=>names[N(t.name)]).ToArray();var oldBinds=skin.sharedMesh.bindposes;var binds=mesh.bindposes;if(oldBinds.Length!=67)throw new Exception("Native bind count");for(int i=0;i<67;i++){int old=Array.FindIndex(skin.bones,t=>N(t.name)==N(dense.bones[i].name));for(int k=0;k<16;k++)if(Mathf.Abs(oldBinds[old][k]-binds[i][k])>1e-5f)throw new Exception("Original native bind mismatch "+i);}
 skin.sharedMesh=mesh;skin.bones=mapped;skin.sharedMaterials=new[]{dense.sharedMaterial};skin.quality=SkinQuality.Auto;skin.updateWhenOffscreen=true;ground.bones=mapped;
 // Standalone Avatar prevents the dense option retaining the original low mesh/atlas via FBX subasset dependencies.
 var avatar=UnityEngine.Object.Instantiate(a.avatar);avatar.name="Master Original Native Human Avatar";AssetDatabase.DeleteAsset(Dir+"/native-human-avatar.asset");AssetDatabase.CreateAsset(avatar,Dir+"/native-human-avatar.asset");a.avatar=avatar;
 var fingers=actor.GetComponent<NativeFingerPoseDriver>();var serialized=new SerializedObject(fingers);var prop=serialized.FindProperty("pose");var fist=UnityEngine.Object.Instantiate((NativeFingerPose)prop.objectReferenceValue);fist.sourceAvatar=avatar;AssetDatabase.DeleteAsset(Dir+"/dense-fist.asset");AssetDatabase.CreateAsset(fist,Dir+"/dense-fist.asset");prop.objectReferenceValue=fist;serialized.ApplyModifiedPropertiesWithoutUndo();
 var data=DensePoseData.Read(AssetDatabase.LoadAssetAtPath<TextAsset>(Dir+"/pose-proof.bytes").bytes);if(data.vertices.Length!=mesh.vertexCount)throw new Exception("Dense full reference count");var foot=new HashSet<int>();var body=new HashSet<int>();var rows=new List<string>{"state,phase,bodySupport,fullMinimum,index"};float originalCap=ground.maxCorrection;
 var controller=(AnimatorController)a.runtimeAnimatorController;var hip=mapped.Single(t=>N(t.name)=="Hips");var baseTransforms=a.GetComponentsInChildren<Transform>();var pos=baseTransforms.Select(t=>t.localPosition).ToArray();var rot=baseTransforms.Select(t=>t.localRotation).ToArray();var scale=baseTransforms.Select(t=>t.localScale).ToArray();
 foreach(var state in controller.layers[0].stateMachine.states){if(!(state.state.motion is AnimationClip clip))continue;int steps=Math.Max(16,Mathf.CeilToInt(clip.length*15));for(int f=0;f<=steps;f++){
 ground.ResetForSample();a.Play("Base Layer."+state.state.name,0,Mathf.Min((float)f/steps,.999999f));a.Update(0);fingers.ApplyForReview(!new[]{"Greeting","Dance"}.Contains(state.state.name),1);overlay.EvaluateForReview(state.state.name,(float)f/steps,1,false);var hp=a.transform.InverseTransformPoint(hip.position);hp.x=overlay.hipBindAnchor.x;hp.z=overlay.hipBindAnchor.z;hip.position=a.transform.TransformPoint(hp);
 var matrices=data.Matrices(mapped);bool lying=state.state.name=="Defeat";int at=-1;float min=float.PositiveInfinity;if(lying){for(int v=0;v<data.vertices.Length;v++){float y=data.Point(v,matrices).y;if(y<min){min=y;at=v;}}body.Add(at);}else{min=data.Minimum(data.feet,matrices,out at);foot.Add(at);}rows.Add(state.state.name+","+(float)f/steps+","+lying+","+min+","+at);
 }}
 ground.shoePoints=foot.Select(data.Support).ToArray();ground.maxCorrection=originalCap;overlay.supportPoints=ground.shoePoints;overlay.defeatBodyPoints=body.Select(data.Support).ToArray();overlay.baseMaxCorrection=originalCap;
 for(int i=0;i<baseTransforms.Length;i++){baseTransforms[i].localPosition=pos[i];baseTransforms[i].localRotation=rot[i];baseTransforms[i].localScale=scale[i];}ground.ResetForSample();
 var mode=actor.AddComponent<OriginalDensityViewMode>();mode.target=skin;mode.originalDense=mesh;mode.originalAtlas=dense.sharedMaterial; // No low mesh or retopo material dependency in this prefab.
 PrefabUtility.SaveAsPrefabAsset(actor,Dir+"/MasterOriginalDensityReview.prefab");AssetDatabase.SaveAssets();Directory.CreateDirectory("NativeDenseEvidence/Fighter");File.WriteAllLines("NativeDenseEvidence/Fighter/ground-training.csv",rows);File.WriteAllLines("NativeDenseEvidence/Fighter/full-foot-indices.txt",data.feet.Select(i=>i.ToString()));File.WriteAllLines("NativeDenseEvidence/Fighter/dense-support-indices.txt",foot.Select(i=>i.ToString()));File.WriteAllLines("NativeDenseEvidence/Fighter/dense-body-indices.txt",body.Select(i=>i.ToString()));var deps=AssetDatabase.GetDependencies(Dir+"/MasterOriginalDensityReview.prefab",true);File.WriteAllLines("NativeDenseEvidence/Fighter/dependencies.txt",deps);if(deps.Any(p=>p.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase)))throw new Exception("Unexpected FBX/low mesh dependency; inspect dependency report");Debug.Log("AGENT_RESULT original dense playable review generated foot="+foot.Count+" body="+body.Count+" originalCap="+originalCap);
 }finally{UnityEngine.Object.DestroyImmediate(actor);}EnrichNativeBody();AuditFinalData();}
 public static void BuildPreviewPlayer(){if(Environment.GetEnvironmentVariable("LIGHTFIGHT_DENSE_SKIP_TRAINING")!="1")Build();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var qa=new GameObject("Current FighterView original-density review").AddComponent<DenseFighterCompatibilityProbe>();qa.prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"/MasterOriginalDensityReview.prefab");qa.proofBytes=AssetDatabase.LoadAssetAtPath<TextAsset>(Dir+"/pose-proof.bytes");qa.acceptedPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Source);qa.fullFootIndices=File.ReadAllLines("NativeDenseEvidence/Fighter/full-foot-indices.txt").Select(int.Parse).ToArray();RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.45f,.43f,.4f);var light=new GameObject("Original atlas key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.2f;light.transform.rotation=Quaternion.Euler(45,-30,0);var cam=new GameObject("Playable dense camera").AddComponent<Camera>();cam.allowHDR=true;cam.orthographic=true;cam.orthographicSize=1.32f;cam.backgroundColor=new Color(.1f,.12f,.15f,0);cam.clearFlags=CameraClearFlags.SolidColor;var center=new Vector3(0,1.06f,0);cam.transform.position=center+new Vector3(.2f,.1f,1).normalized*6;cam.transform.LookAt(center);var rt=new RenderTexture(800,1000,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);AssetDatabase.DeleteAsset(Dir+"/playable-review.renderTexture");AssetDatabase.CreateAsset(rt,Dir+"/playable-review.renderTexture");cam.targetTexture=rt;var fx=cam.gameObject.AddComponent<FittedFilmicCamera>();fx.filmicShader=Shader.Find("Hidden/LighFight/FittedFilmic");if(!fx.filmicShader)fx.filmicShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/ColorCandidate/FittedFilmic.shader");qa.captureCamera=cam;var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.01f,0);floor.transform.localScale=new Vector3(8,.02f,8);var mat=new Material(Shader.Find("Standard"));mat.color=new Color(.19f,.21f,.23f);mat.SetFloat("_Glossiness",0);AssetDatabase.DeleteAsset(Dir+"/review-floor.mat");AssetDatabase.CreateAsset(mat,Dir+"/review-floor.mat");floor.GetComponent<Renderer>().sharedMaterial=mat;string scene=Dir+"/playable-review.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{scene},locationPathName="NativeSupportPlayer.app",target=BuildTarget.StandaloneOSX,options=BuildOptions.Development});if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Dense playable review build failed");}
